-- 166: Original BrillaPrep WASSCE BrillaPrep transitional Building Construction beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_166_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_166_guard;
INSERT INTO _migration_166_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_011' AND NOT (q.topic_id IS 'topic_was_building_b003_3' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When is a wide strip foundation preferred to a narrow strip foundation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. When no wall load reaches the ground","B. When the soil must be deliberately overstressed","C. When the soil has lower safe bearing capacity or the wall load is higher","D. When the trench is used only for drainage"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Increasing foundation width spreads the wall load over a larger ground area and reduces bearing pressure on weaker soil. Therefore the correct answer is C: When the soil has lower safe bearing capacity or the wall load is higher.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_011' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_166_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_012' AND NOT (q.topic_id IS 'topic_was_building_b003_3' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a damp-proof course in a masonry wall?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Carry the entire roof load across an opening","B. Bond the roof covering to the rafters","C. Ventilate the underground drainage system","D. Interrupt capillary rise of ground moisture through the wall"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An impervious continuous layer above ground level blocks rising damp that would otherwise damage finishes and indoor conditions. Therefore the correct answer is D: Interrupt capillary rise of ground moisture through the wall.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_012' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_166_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_013' AND NOT (q.topic_id IS 'topic_was_building_b003_3' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is lean concrete sometimes placed as blinding at the bottom of a foundation excavation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Provide a clean level working surface and separate structural concrete from soil","B. Replace all reinforcement in the footing","C. Increase groundwater flow into the trench","D. Act as the final decorative floor finish"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Blinding prevents contamination of structural concrete, protects reinforcement cover and gives a stable accurate base for setting out the footing. Therefore the correct answer is A: Provide a clean level working surface and separate structural concrete from soil.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_013' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_166_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_014' AND NOT (q.topic_id IS 'topic_was_building_b003_3' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which foundation is most appropriate where isolated columns carry concentrated loads on competent soil?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A damp-proof membrane without concrete","B. Individual pad foundations beneath the columns","C. A timber floor laid directly on topsoil","D. A cavity wall built below every column"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Pad foundations distribute each column reaction over sufficient soil area while remaining economical where loads and ground conditions permit. Therefore the correct answer is B: Individual pad foundations beneath the columns.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_014' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_166_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_015' AND NOT (q.topic_id IS 'topic_was_building_b003_3' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main reason for compacting hardcore beneath a ground floor slab?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Create large connected voids below the slab","B. Prevent cement hydration in the slab","C. Reduce later settlement and provide a stable load-spreading base","D. Eliminate the need for any surface finish"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Well-graded compacted hardcore limits movement and supports the slab uniformly; loose fill can consolidate and cause cracking or local sinking. Therefore the correct answer is C: Reduce later settlement and provide a stable load-spreading base.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_015' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
